    {
      "ref": "[D505]",
      "area": "contact",
      "claim": "Roblox auto-blocks direct messages from users under 13 by default.",
      "stance": "mitigation",
      "quote": "Roblox Boosts Child-Safety Settings by Auto-Blocking DMs to Users Under 13, Increases Parental Controls on Violent, Sexually Themed Content."
    },
    {
      "ref": "[D504]",
      "area": "contact",
      "claim": "A parent created a safety guide covering scams, privacy, and settings.",
      "stance": "neutral",
      "quote": "Made a simple Roblox safety guide for kids (covers scams, privacy, and settings)."
    },
    {
      "ref": "[D506]",
      "area": "contact",
      "claim": "A parent reports that Roblox's parent controls are ineffective and give a false sense of security.",
      "stance": "risk",
      "quote": "Roblox's parent controls in my opinion are worse than having no parent controls. They don't actually do anything and they give parents the peace"
    },
    {
      "ref": "[D507]",
      "area": "content",
      "claim": "A parent reports that Roblox is not safe for kids and actively targets children.",
      "stance": "risk",
      "quote": "Roblox is not safe for kids - they are actively targeting kids. This ... How do other parents figure out which Roblox games are actually safe?"
    },
    {
      "ref": "[D508]",
      "area": "content",
      "claim": "A parent notes that many 6-year-olds play Roblox and their child is asking to join.",
      "stance": "neutral",
      "quote": "Mother of our kid and I are considering whether to let our 6-year-old play Roblox. Many of his classmates already play it, and he’s been asking for it"
    },
    {
      "ref": "[D509]",
      "area": "contact",
      "claim": "A parent states that constant monitoring of a child on Roblox is required, implying the platform is unsafe.",
      "stance": "risk",
      "quote": "If you have to monitor the child every moment they use something, they shouldn't be using it. This applies to games, toys….everything."
    },
    {
      "ref": "[D510]",
      "area": "content",
      "claim": "A parent warns that user-generated games on Roblox may contain adult content such as condo games.",
      "stance": "risk",
      "quote": "One of the main risks parents should know about Roblox are user-generated games, or \"condo games,\" that feature adult content, such as"
    },
    {
      "ref": "[D512]",
      "area": "contact",
      "claim": "A parent reports that Roblox ignores user reports and relies only on automated moderation bots.",
      "stance": "risk",
      "quote": "Reporting people only really works if they're trying to scam in chat ... Roblox ignores rule reports and relies solely on their moderation bots"
    },
    {
      "ref": "[D513]",
      "area": "contact",
      "claim": "A parent describes a scam where an impersonator tries to steal accounts via chat.",
      "stance": "risk",
      "quote": "This person is an impersonator of a moderator, probably trying to scam! Please ban them so nobody gets scammed! r/crosstradingroblox."
    },
    {
      "ref": "[D514]",
      "area": "contact",
      "claim": "A parent warns that scammers use Discord group chats to target Roblox players.",
      "stance": "risk",
      "quote": "If you are in a discord group for a roblox game, please be aware of these scam messages sent through the report systems where a person has a"
    },
    {
      "ref": "[D515]",
      "area": "money",
      "claim": "A parent reports being falsely banned for scamming after warning others about fraud.",
      "stance": "risk",
      "quote": "then the next day I receive a ONE DAY BAN for \"scamming players\" with the evidence being me saying in chat \"this is a scam guys\". Like wth,"
    },
    {
      "ref": "[D516]",
      "area": "money",
      "claim": "A parent advises reporting scammers by naming them in chat rather than engaging with them.",
      "stance": "mitigation",
      "quote": "You should just report the player and say in chat (their username) is a scammer, and then leave."
    },
    {
      "ref": "[D519]",
      "area": "money",
      "claim": "A parent asks whether scammers who steal money from games get banned.",
      "stance": "neutral",
      "quote": "This person stole 400 bucks from me, do they get banned?"
    }
  ]
